package com.esn.smp.gameplay;
import com.esn.smp.data.ESNDataStore;import org.bukkit.*;import org.bukkit.command.*;import org.bukkit.entity.Player;import org.bukkit.event.*;import org.bukkit.event.inventory.InventoryClickEvent;import org.bukkit.inventory.*;import org.bukkit.inventory.meta.*;import org.bukkit.plugin.java.JavaPlugin;import java.util.*;
public final class AdminControlCenter implements Listener,CommandExecutor{
 private final JavaPlugin plugin;private final SMPGameplay gameplay;private final ESNDataStore data;private final Map<UUID,UUID> selected=new HashMap<>();
 public AdminControlCenter(JavaPlugin plugin,SMPGameplay gameplay,ESNDataStore data){this.plugin=plugin;this.gameplay=gameplay;this.data=data;}
 public boolean onCommand(CommandSender s,Command c,String l,String[] a){if(!(s instanceof Player p)){s.sendMessage("Players only.");return true;}if(c.getName().equalsIgnoreCase("modmenu")){if(!p.hasPermission("esnsmp.staff")){p.sendMessage(ChatColor.RED+"No permission.");return true;}openMod(p);return true;}if(!p.hasPermission("esnsmp.admin")){p.sendMessage(ChatColor.RED+"No permission.");return true;}open(p);return true;}
 private ItemStack item(Material m,String name,String... lore){ItemStack i=new ItemStack(m);ItemMeta im=i.getItemMeta();im.setDisplayName(name);im.setLore(Arrays.asList(lore));i.setItemMeta(im);return i;}
 private ItemStack head(Player q){ItemStack i=new ItemStack(Material.PLAYER_HEAD);SkullMeta m=(SkullMeta)i.getItemMeta();m.setOwningPlayer(q);m.setDisplayName(ChatColor.YELLOW+q.getName());double max=q.getAttribute(org.bukkit.attribute.Attribute.MAX_HEALTH)==null?20:q.getAttribute(org.bukkit.attribute.Attribute.MAX_HEALTH).getValue();m.setLore(List.of(ChatColor.GREEN+"ONLINE",ChatColor.GRAY+"Health: "+Math.round(q.getHealth())+"/"+Math.round(max),ChatColor.GRAY+"World: "+q.getWorld().getName(),ChatColor.GRAY+"Mode: "+q.getGameMode(),ChatColor.GRAY+"Click to manage player"));i.setItemMeta(m);return i;}
 private void open(Player p){Inventory i=Bukkit.createInventory(null,54,ChatColor.DARK_RED+"ESN Admin Control Center");i.setItem(10,item(Material.EMERALD,ChatColor.GREEN+"Server Shop",ChatColor.GRAY+"Open /shop."));i.setItem(11,item(Material.ENDER_CHEST,ChatColor.LIGHT_PURPLE+"Loot Crates",ChatColor.GRAY+"Open /crates."));i.setItem(12,item(Material.COMPASS,ChatColor.AQUA+"Diagnostics",ChatColor.GRAY+"Run /diagnostics."));i.setItem(13,item(Material.NETHER_STAR,ChatColor.GOLD+"Spawn World Boss",ChatColor.GRAY+"Run /boss world."));i.setItem(14,item(Material.BEACON,ChatColor.LIGHT_PURPLE+"Events",ChatColor.GRAY+"View the current ESN event."));i.setItem(15,item(Material.CLOCK,ChatColor.YELLOW+"Event Calendar",ChatColor.GRAY+"Open /calendar."));i.setItem(16,item(Material.PAPER,ChatColor.WHITE+"Staff Help",ChatColor.GRAY+"Open /staff."));int slot=27;for(Player q:Bukkit.getOnlinePlayers()){if(slot>=45)break;i.setItem(slot++,head(q));}i.setItem(49,item(Material.BARRIER,ChatColor.RED+"Close"));p.openInventory(i);}
 private void openMod(Player p){Inventory i=Bukkit.createInventory(null,54,ChatColor.DARK_RED+"ESN Moderation Center");i.setItem(4,item(Material.SHIELD,ChatColor.GOLD+"ESN Moderation",ChatColor.GRAY+"Select an online player below."));if(p.hasPermission("esnsmp.owner"))i.setItem(8,item(Material.NETHER_STAR,ChatColor.LIGHT_PURPLE+"Staff Ranks",ChatColor.GRAY+"Owner-only: click a player, then assign their rank."));int slot=18;for(Player q:Bukkit.getOnlinePlayers()){if(slot>=45)break;i.setItem(slot++,head(q));}i.setItem(49,item(Material.BARRIER,ChatColor.RED+"Close"));p.openInventory(i);}
 private void modPlayer(Player a,Player t){selected.put(a.getUniqueId(),t.getUniqueId());Inventory i=Bukkit.createInventory(null,36,ChatColor.DARK_RED+"Moderate • "+t.getName());i.setItem(4,head(t));i.setItem(10,item(Material.ICE,ChatColor.AQUA+"Freeze",ChatColor.GRAY+"Freeze this player."));i.setItem(11,item(Material.BOOK,ChatColor.YELLOW+"Warn",ChatColor.GRAY+"Send a staff warning."));i.setItem(12,item(Material.NAME_TAG,ChatColor.RED+"Mute",ChatColor.GRAY+"Mute until restart."));i.setItem(13,item(Material.IRON_BOOTS,ChatColor.YELLOW+"Kick",ChatColor.GRAY+"Kick from server."));i.setItem(14,item(Material.BARRIER,ChatColor.DARK_RED+"Ban",ChatColor.GRAY+"Ban from server."));i.setItem(15,item(Material.CHEST,ChatColor.GOLD+"Inventory",ChatColor.GRAY+"Open /invsee."));i.setItem(16,item(Material.ENDER_CHEST,ChatColor.DARK_PURPLE+"Ender Chest",ChatColor.GRAY+"Open /ecsee."));i.setItem(22,item(Material.WRITABLE_BOOK,ChatColor.GOLD+"History",ChatColor.GRAY+"View moderation history."));if(a.hasPermission("esnsmp.owner")){i.setItem(24,item(Material.COPPER_INGOT,ChatColor.YELLOW+"Set Helper",ChatColor.GRAY+"Limited moderation access."));i.setItem(25,item(Material.IRON_INGOT,ChatColor.AQUA+"Set Moderator",ChatColor.GRAY+"Standard moderation access."));i.setItem(26,item(Material.GOLD_INGOT,ChatColor.GOLD+"Set Senior Mod",ChatColor.GRAY+"Expanded moderation access."));i.setItem(27,item(Material.BARRIER,ChatColor.RED+"Remove Staff",ChatColor.GRAY+"Remove ESN staff permissions."));}i.setItem(31,item(Material.ARROW,ChatColor.YELLOW+"Back"));a.openInventory(i);}
 private void playerMenu(Player a,Player t){selected.put(a.getUniqueId(),t.getUniqueId());long bal=0;try{bal=data.getBalance(t);}catch(Exception ignored){}Inventory i=Bukkit.createInventory(null,54,ChatColor.DARK_RED+"Manage • "+t.getName());i.setItem(4,head(t));i.setItem(10,item(Material.ICE,ChatColor.AQUA+"Freeze / Unfreeze",ChatColor.GRAY+"Toggle ESN freeze."));i.setItem(11,item(Material.IRON_BOOTS,ChatColor.YELLOW+"Kick",ChatColor.GRAY+"Kick this player."));i.setItem(12,item(Material.BARRIER,ChatColor.DARK_RED+"Ban",ChatColor.GRAY+"Permanently ban this player."));i.setItem(13,item(Material.CHEST,ChatColor.GOLD+"Inventory",ChatColor.GRAY+"Open /invsee."));i.setItem(14,item(Material.ENDER_CHEST,ChatColor.DARK_PURPLE+"Ender Chest",ChatColor.GRAY+"Open /ecsee."));i.setItem(15,item(Material.ENDER_PEARL,ChatColor.AQUA+"Teleport To",ChatColor.GRAY+"Teleport to "+t.getName()+"."));i.setItem(16,item(Material.LEAD,ChatColor.GREEN+"Summon Player",ChatColor.GRAY+"Teleport player to you."));i.setItem(19,item(Material.GOLDEN_APPLE,ChatColor.GREEN+"Heal + Feed",ChatColor.GRAY+"Restore health, food and fire."));i.setItem(20,item(Material.GRASS_BLOCK,ChatColor.GREEN+"Survival",ChatColor.GRAY+"Set Survival mode."));i.setItem(21,item(Material.DIAMOND_BLOCK,ChatColor.AQUA+"Creative",ChatColor.GRAY+"Set Creative mode."));i.setItem(22,item(Material.FEATHER,ChatColor.WHITE+"Spectator",ChatColor.GRAY+"Set Spectator mode."));i.setItem(23,item(Material.BOOK,ChatColor.YELLOW+"Warn",ChatColor.GRAY+"Send an ESN staff warning."));i.setItem(24,item(Material.NAME_TAG,ChatColor.RED+"Mute",ChatColor.GRAY+"Mute until restart."));i.setItem(25,item(Material.WRITABLE_BOOK,ChatColor.GOLD+"History",ChatColor.GRAY+"Open moderation history."));i.setItem(28,item(Material.GOLD_INGOT,ChatColor.GOLD+"+1,000 Coins",ChatColor.GRAY+"Balance: "+bal));i.setItem(29,item(Material.GOLD_BLOCK,ChatColor.GOLD+"+10,000 Coins",ChatColor.GRAY+"Balance: "+bal));i.setItem(30,item(Material.SUNFLOWER,ChatColor.RED+"-1,000 Coins",ChatColor.GRAY+"Balance: "+bal));i.setItem(32,item(Material.TRIPWIRE_HOOK,ChatColor.LIGHT_PURPLE+"Give ESN Crate Key",ChatColor.GRAY+"Give a standard ESN crate key."));i.setItem(33,item(Material.NETHER_STAR,ChatColor.LIGHT_PURPLE+"Give Realm 100 Key",ChatColor.GRAY+"Run /megacratekey 100 for this player."));i.setItem(49,item(Material.ARROW,ChatColor.YELLOW+"Back"));a.openInventory(i);}
 private Player target(Player a){UUID id=selected.get(a.getUniqueId());return id==null?null:Bukkit.getPlayer(id);}
 private void msg(Player a,String s){a.sendMessage(ChatColor.GOLD+"[Admin] "+ChatColor.WHITE+s);}
 private void staffCmd(Player a,String cmd,Player t){a.closeInventory();a.performCommand(cmd+" "+t.getName());}
 private void staffRank(Player owner,Player target,String rank){if(!owner.hasPermission("esnsmp.owner")){msg(owner,"Only ESN Owners can change staff ranks.");return;}String[] perms={"esnsmp.staff","esnsmp.staff.helper","esnsmp.staff.moderator","esnsmp.staff.seniormod"};for(String perm:perms)target.addAttachment(plugin,perm,false);if(!rank.equals("none")){target.addAttachment(plugin,"esnsmp.staff",true);target.addAttachment(plugin,"esnsmp.staff."+rank,true);}msg(owner,rank.equals("none")?"Removed staff access from "+target.getName()+".":"Set "+target.getName()+" to "+rank+".");target.sendMessage(ChatColor.GOLD+"Your ESN staff rank is now "+rank+".");modPlayer(owner,target);}
 @EventHandler public void click(InventoryClickEvent e){String title=e.getView().getTitle();boolean root=title.equals(ChatColor.DARK_RED+"ESN Admin Control Center"),manage=title.startsWith(ChatColor.DARK_RED+"Manage • "),modroot=title.equals(ChatColor.DARK_RED+"ESN Moderation Center"),modmanage=title.startsWith(ChatColor.DARK_RED+"Moderate • ");if(!root&&!manage&&!modroot&&!modmanage)return;e.setCancelled(true);if(!(e.getWhoClicked() instanceof Player a))return;if((root||manage)&&!a.hasPermission("esnsmp.admin"))return;if((modroot||modmanage)&&!a.hasPermission("esnsmp.staff"))return;int s=e.getRawSlot();if(modroot){if(s==49){a.closeInventory();return;}ItemStack x=e.getCurrentItem();if(x!=null&&x.getType()==Material.PLAYER_HEAD&&x.getItemMeta() instanceof SkullMeta sm&&sm.getOwningPlayer()!=null){Player t=Bukkit.getPlayer(sm.getOwningPlayer().getUniqueId());if(t==null){msg(a,"Player went offline.");openMod(a);}else modPlayer(a,t);}return;}if(modmanage){if(s==31){openMod(a);return;}Player t=target(a);if(t==null){msg(a,"Player is no longer online.");openMod(a);return;}switch(s){case 10->staffCmd(a,"freeze",t);case 11->{t.sendMessage(ChatColor.RED+"Staff warning: Follow ESN SMP rules.");msg(a,"Warned "+t.getName()+".");}case 12->staffCmd(a,"mute",t);case 13->{t.kickPlayer("Kicked by ESN staff.");msg(a,"Kicked "+t.getName()+".");openMod(a);}case 14->{Bukkit.getBanList(BanList.Type.NAME).addBan(t.getName(),"Banned by ESN staff.",null,a.getName());t.kickPlayer("Banned by ESN staff.");msg(a,"Banned "+t.getName()+".");openMod(a);}case 15->staffCmd(a,"invsee",t);case 16->staffCmd(a,"ecsee",t);case 22->staffCmd(a,"history",t);case 24->{if(a.hasPermission("esnsmp.owner"))staffRank(a,t,"helper");}case 25->{if(a.hasPermission("esnsmp.owner"))staffRank(a,t,"moderator");}case 26->{if(a.hasPermission("esnsmp.owner"))staffRank(a,t,"seniormod");}case 27->{if(a.hasPermission("esnsmp.owner"))staffRank(a,t,"none");}}return;}if(root){switch(s){case 10->gameplay.openShop(a);case 11->gameplay.openCrates(a);case 12->{a.closeInventory();a.performCommand("diagnostics");}case 13->{a.closeInventory();a.performCommand("boss world");}case 14->{a.closeInventory();a.performCommand("events2");}case 15->{a.closeInventory();a.performCommand("calendar");}case 16->{a.closeInventory();a.performCommand("staff");}case 49->a.closeInventory();default->{ItemStack x=e.getCurrentItem();if(x!=null&&x.getType()==Material.PLAYER_HEAD&&x.getItemMeta() instanceof SkullMeta sm&&sm.getOwningPlayer()!=null){Player t=Bukkit.getPlayer(sm.getOwningPlayer().getUniqueId());if(t==null){msg(a,"Player went offline.");open(a);}else playerMenu(a,t);}}}return;}if(s==49){open(a);return;}Player t=target(a);if(t==null){msg(a,"Player is no longer online.");open(a);return;}try{switch(s){case 10->staffCmd(a,"freeze",t);case 11->{t.kickPlayer("Kicked by ESN staff.");msg(a,"Kicked "+t.getName()+".");open(a);}case 12->{Bukkit.getBanList(BanList.Type.NAME).addBan(t.getName(),"Banned by ESN staff.",null,a.getName());t.kickPlayer("Banned by ESN staff.");msg(a,"Banned "+t.getName()+".");open(a);}case 13->staffCmd(a,"invsee",t);case 14->staffCmd(a,"ecsee",t);case 15->{a.teleport(t);msg(a,"Teleported to "+t.getName()+".");}case 16->{t.teleport(a);msg(a,"Summoned "+t.getName()+".");}case 19->{double max=t.getAttribute(org.bukkit.attribute.Attribute.MAX_HEALTH)==null?20:t.getAttribute(org.bukkit.attribute.Attribute.MAX_HEALTH).getValue();t.setHealth(max);t.setFoodLevel(20);t.setSaturation(20);t.setFireTicks(0);msg(a,"Healed and fed "+t.getName()+".");playerMenu(a,t);}case 20->{t.setGameMode(GameMode.SURVIVAL);msg(a,"Set "+t.getName()+" to Survival.");playerMenu(a,t);}case 21->{t.setGameMode(GameMode.CREATIVE);msg(a,"Set "+t.getName()+" to Creative.");playerMenu(a,t);}case 22->{t.setGameMode(GameMode.SPECTATOR);msg(a,"Set "+t.getName()+" to Spectator.");playerMenu(a,t);}case 23->{t.sendMessage(ChatColor.RED+"Staff warning: Follow ESN SMP rules.");msg(a,"Warned "+t.getName()+".");}case 24->staffCmd(a,"mute",t);case 25->staffCmd(a,"history",t);case 28->{data.deposit(t,1000);msg(a,"Added 1,000 Coins to "+t.getName()+".");playerMenu(a,t);}case 29->{data.deposit(t,10000);msg(a,"Added 10,000 Coins to "+t.getName()+".");playerMenu(a,t);}case 30->{if(data.withdraw(t,1000))msg(a,"Removed 1,000 Coins from "+t.getName()+".");else msg(a,t.getName()+" has less than 1,000 Coins.");playerMenu(a,t);}case 32->{Map<Integer,ItemStack> left=t.getInventory().addItem(LootDrops.key());left.values().forEach(x->t.getWorld().dropItemNaturally(t.getLocation(),x));msg(a,"Gave "+t.getName()+" an ESN Crate Key.");}case 33->{ItemStack k=MegaCrates.key(99);Map<Integer,ItemStack> left=t.getInventory().addItem(k);left.values().forEach(x->t.getWorld().dropItemNaturally(t.getLocation(),x));msg(a,"Gave "+t.getName()+" a Realm 100 Crate Key.");}}}catch(Exception ex){msg(a,"Action failed safely: "+ex.getMessage());plugin.getLogger().warning("[Admin Center] "+ex.getMessage());}}
}
